package cn.nebulaedata.cccs.nebuwork.backend.api.workbenchservice;

import cn.nebulaedata.cccs.nebuwork.backend.api.identity.RequestIdentity;
import com.fasterxml.jackson.databind.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.io.ClassPathResource;
import org.springframework.http.*;
import org.springframework.util.MultiValueMap;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.method.annotation.StreamingResponseBody;
import javax.servlet.http.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiSupport.ok;
import static cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiSupport.map;
import static cn.nebulaedata.cccs.nebuwork.backend.api.workbenchservice.ServiceSupport.*;

@RestController
public class ServiceController {
    @org.springframework.beans.factory.annotation.Autowired private cn.nebulaedata.cccs.nebuwork.backend.api.identity.SessionFilter sessions;
    private final WorkbenchServices services;private final ServiceOperations operations;private final ServiceAccess access;private final ServiceProtocol protocol;
    public ServiceController(WorkbenchServices services,ServiceOperations operations,ServiceAccess access,ServiceProtocol protocol){this.services=services;this.operations=operations;this.access=access;this.protocol=protocol;}
    @ExceptionHandler(cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiException.class) public ResponseEntity<Object> error(cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiException e,HttpServletRequest request){boolean oauth=request.getRequestURI().contains("/api/service-oauth/")&&!request.getRequestURI().contains("/requests/");Object body=oauth?map("error",e.status==401?"invalid_client":e.status==400?"invalid_grant":e.status==403?"access_denied":"invalid_request","error_description",e.getMessage()):cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiSupport.error(e.status,e.getMessage());return ResponseEntity.status(e.status).header("Cache-Control","no-store").contentType(MediaType.APPLICATION_JSON).body(body);}
    @GetMapping("/api/workbenches/{wb}/service") public Object get(@PathVariable String wb,HttpServletRequest r){return ok(services.get(RequestIdentity.actor(r),wb));}
    @PostMapping("/api/workbenches/{wb}/service") public Object save(@PathVariable String wb,@RequestBody JsonNode body,HttpServletRequest r){return ok(services.save(RequestIdentity.actor(r),wb,body));}
    @PostMapping("/api/workbenches/{wb}/service/publish") public Object publish(@PathVariable String wb,@RequestBody JsonNode body,HttpServletRequest r){return ok(services.publish(RequestIdentity.actor(r),wb,body.path("revision").asLong(-1)));}
    @PostMapping("/api/workbenches/{wb}/service/preview") public Object preview(@PathVariable String wb,@RequestBody JsonNode body,HttpServletRequest r){return ok(services.preview(RequestIdentity.actor(r),wb,body.path("revision").asLong(-1)));}
    @PostMapping("/api/workbenches/{wb}/service/test/{capability}") public Object test(@PathVariable String wb,@PathVariable String capability,@RequestBody JsonNode body,@RequestHeader("Idempotency-Key")String key,HttpServletRequest r){JsonNode release=services.json.valueToTree(services.preview(RequestIdentity.actor(r),wb,body.path("revision").asLong(-1)));com.fasterxml.jackson.databind.node.ObjectNode input=services.json.createObjectNode();input.put("projectId",body.path("projectId").asText());input.set("input",body.path("input"));input.put("releaseId",release.path("id").asText());return ok(operations.invoke(access.principal(r),wb,capability,input,key,"test"));}
    @GetMapping("/api/workbenches/{wb}/service/assets/{id}") public Object assetRead(@PathVariable String wb,@PathVariable String id,HttpServletRequest r){return ok(services.assetView(RequestIdentity.actor(r),wb,id));}
    @GetMapping("/api/workbenches/{wb}/service/releases") public Object releases(@PathVariable String wb,HttpServletRequest r){return ok(services.releases(RequestIdentity.actor(r),wb));}
    @PostMapping("/api/workbenches/{wb}/service/{action:activate|disable}") public Object change(@PathVariable String wb,@PathVariable String action,@RequestBody JsonNode body,HttpServletRequest r){return ok(services.change(RequestIdentity.actor(r),wb,action,body));}
    @PostMapping("/api/workbenches/{wb}/service/assets") public Object asset(@PathVariable String wb,@RequestBody JsonNode body,HttpServletRequest r){return ok(services.assetAdd(RequestIdentity.actor(r),wb,body));}
    @GetMapping("/api/workbenches/{wb}/service/operations") public Object operations(@PathVariable String wb,HttpServletRequest r){return ok(operations.list(RequestIdentity.actor(r),wb));}
    @GetMapping("/api/workbenches/{wb}/service/apps") public Object apps(@PathVariable String wb,HttpServletRequest r){return ok(access.apps(RequestIdentity.actor(r),wb));}
    @PostMapping("/api/workbenches/{wb}/service/apps") public Object app(@PathVariable String wb,@RequestBody JsonNode body,@RequestHeader("Idempotency-Key")String key,HttpServletRequest r){return ok(access.saveApp(RequestIdentity.actor(r),wb,body,key));}
    @PostMapping("/api/workbenches/{wb}/service/apps/{app}/rotate") public Object rotate(@PathVariable String wb,@PathVariable String app,@RequestBody JsonNode body,HttpServletRequest r){return ok(access.rotate(RequestIdentity.actor(r),wb,app,body.path("revision").asLong(-1)));}
    @GetMapping("/api/workbench-services/{wb}/manifest") public Object manifest(@PathVariable String wb,@RequestParam(required=false)String releaseId,HttpServletRequest r){return ok(services.manifest(access.principal(r),wb,releaseId));}
    @GetMapping("/api/workbench-services/{wb}/openapi.json") public Object openapi(@PathVariable String wb,@RequestParam(required=false)String releaseId,HttpServletRequest r){com.fasterxml.jackson.databind.node.ObjectNode document=services.json.valueToTree(services.openapi(access.principal(r),wb,releaseId));document.putArray("servers").addObject().put("url",access.base());return document;}
    @PostMapping("/api/workbench-services/{wb}/capabilities/{capability}/invoke") public ResponseEntity<Object> invoke(@PathVariable String wb,@PathVariable String capability,@RequestBody JsonNode body,@RequestHeader("Idempotency-Key")String key,HttpServletRequest r){Object result=operations.invoke(access.principal(r),wb,capability,body,key,body.has("instanceId")?"page":"api");String state=services.json.valueToTree(result).path("status").asText();return ResponseEntity.status(Arrays.asList("succeeded","failed","cancelled").contains(state)?200:202).body(ok(result));}
    @GetMapping("/api/workbench-services/{wb}/operations/{id}") public Object operation(@PathVariable String wb,@PathVariable String id,HttpServletRequest r){return ok(operations.get(access.principal(r),wb,id));}
    @GetMapping("/api/workbench-services/{wb}/operations/{id}/events") public Object events(@PathVariable String wb,@PathVariable String id,@RequestParam(defaultValue="0")long after,HttpServletRequest r){return ok(operations.events(access.principal(r),wb,id,after));}
    @GetMapping(value="/api/workbench-services/{wb}/operations/{id}/stream",produces=MediaType.TEXT_EVENT_STREAM_VALUE) public StreamingResponseBody stream(@PathVariable String wb,@PathVariable String id,@RequestParam(defaultValue="0")long after,@RequestHeader(value="Last-Event-ID",required=false)Long last,HttpServletRequest r){ServiceAccess.Principal principal=access.principal(r);operations.get(principal,wb,id);return out->{long cursor=last==null?Math.max(0,after):Math.max(after,last),deadline=System.currentTimeMillis()+300000;while(System.currentTimeMillis()<deadline){try{if(r.getHeader("Authorization")!=null)access.authenticate(r.getHeader("Authorization").substring(7));else require(sessions.stillAuthenticated(r,principal.owner),401,"登录会话已结束");JsonNode rows=services.json.valueToTree(operations.events(principal,wb,id,cursor));for(JsonNode e:rows){cursor=e.path("id").asLong();out.write(("id: "+cursor+"\nevent: operation\ndata: "+e.path("data")+"\n\n").getBytes(StandardCharsets.UTF_8));}out.write(": heartbeat\n\n".getBytes(StandardCharsets.UTF_8));out.flush();String state=services.json.valueToTree(operations.get(principal,wb,id)).path("status").asText();if(Arrays.asList("succeeded","failed","cancelled","interrupted").contains(state))return;Thread.sleep(1000);}catch(InterruptedException e){Thread.currentThread().interrupt();return;}catch(IOException e){return;}catch(cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiException e){out.write(("event: access-ended\ndata: {\"status\":"+e.status+"}\n\n").getBytes(StandardCharsets.UTF_8));out.flush();return;}}};}
    @PostMapping("/api/workbench-services/{wb}/operations/{id}/commands") public Object command(@PathVariable String wb,@PathVariable String id,@RequestBody JsonNode body,@RequestHeader("Idempotency-Key")String key,HttpServletRequest r){return ok(operations.command(access.principal(r),wb,id,body,key));}
    @PostMapping("/api/workbench-services/{wb}/pages/{page}/instances") public Object createInstance(@PathVariable String wb,@PathVariable String page,@RequestBody JsonNode body,@RequestHeader("Idempotency-Key")String key,HttpServletRequest r){return ok(operations.createInstance(access.principal(r),wb,page,body,key));}
    @GetMapping("/api/workbench-services/{wb}/page-instances/{id}") public Object instance(@PathVariable String wb,@PathVariable String id,HttpServletRequest r){return ok(operations.page(access.principal(r),wb,id));}
    @PostMapping("/api/workbench-services/{wb}/page-instances/{id}/state") public Object state(@PathVariable String wb,@PathVariable String id,@RequestBody JsonNode body,HttpServletRequest r){return ok(operations.saveState(access.principal(r),wb,id,body));}
    @GetMapping(value="/api/workbench-services/{wb}/pages/{page}",produces=MediaType.TEXT_HTML_VALUE) public ResponseEntity<String> page(@PathVariable String wb,@PathVariable String page){require(wb.matches("[A-Za-z0-9_-]{1,128}")&&page.matches(KEY),404,"页面地址无效");return ResponseEntity.ok().header("Cache-Control","no-store").header("Referrer-Policy","no-referrer").header("Content-Security-Policy","default-src 'none'; script-src 'self' 'unsafe-inline'; img-src 'self' data:; font-src data:; style-src 'unsafe-inline'; connect-src 'self'; frame-src 'self' about:; base-uri 'none'; object-src 'none'; frame-ancestors "+access.frameAncestors(wb)).body(resource("workbench-service/page-host.html"));}
    @GetMapping(value="/api/workbench-services/{wb}/host.js",produces="application/javascript") public String host(){return resource("workbench-service/host.js");}
    @GetMapping(value="/api/workbench-services/{wb}/page-sdk.js",produces="application/javascript") public String sdk(){return resource("workbench-service/page-sdk.js");}
    private String resource(String path){try(InputStream in=new ClassPathResource(path).getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);return new String(out.toByteArray(),StandardCharsets.UTF_8);}catch(IOException e){throw new IllegalStateException("页面运行资源缺失",e);}}
    @GetMapping("/api/workbench-services/{wb}/oauth-protected-resource") public Object protectedResource(@PathVariable String wb){return access.metadata(wb);}
    @GetMapping("/.well-known/oauth-protected-resource/api/workbench-services/{wb}/mcp") public Object protectedResourceWellKnown(@PathVariable String wb){return access.metadata(wb);}
    @GetMapping({"/.well-known/oauth-authorization-server/api/service-oauth","/api/service-oauth/.well-known/oauth-authorization-server"}) public Object issuer(){return access.issuer();}
    @GetMapping("/api/service-oauth/authorize") public void authorize(@RequestParam("client_id")String client,@RequestParam("redirect_uri")String redirect,@RequestParam String state,@RequestParam("code_challenge")String challenge,@RequestParam("code_challenge_method")String method,@RequestParam("response_type")String type,@RequestParam(required=false)String resource,HttpServletRequest request,HttpServletResponse response)throws IOException{String id=access.authorize(client,redirect,state,challenge,method,type,resource);response.sendRedirect(access.frontend()+"/#/service-consent?requestId="+id);}
    @GetMapping("/api/service-oauth/requests/{id}") public Object consent(@PathVariable String id,HttpServletRequest r){return ok(access.consent(RequestIdentity.actor(r),id));}
    @PostMapping("/api/service-oauth/requests/{id}/decision") public Object decision(@PathVariable String id,@RequestBody JsonNode body,HttpServletRequest r){return ok(access.decide(RequestIdentity.actor(r),id,body.path("approve").asBoolean()));}
    @PostMapping(value="/api/service-oauth/token",consumes=MediaType.APPLICATION_FORM_URLENCODED_VALUE) public Object token(@RequestParam MultiValueMap<String,String> params,HttpServletResponse response){params.forEach((k,v)->require(v.size()==1,400,"OAuth 参数不能重复"));response.setHeader("Cache-Control","no-store");return access.exchange(params.getFirst("grant_type"),params.getFirst("client_id"),params.getFirst("client_secret"),params.getFirst("code"),params.getFirst("redirect_uri"),params.getFirst("code_verifier"),params.getFirst("resource"));}
    @PostMapping("/api/service-oauth/revoke") public Object revoke(@RequestParam String token){access.revoke(token);return map();}
    @RequestMapping(value="/api/workbench-services/{wb}/mcp",method={RequestMethod.POST,RequestMethod.GET,RequestMethod.DELETE}) public ResponseEntity<byte[]> mcp(@PathVariable String wb,@RequestBody(required=false)String body,HttpServletRequest r){return protocol.proxy(access.principal(r),wb,r.getHeader("Authorization"),r.getMethod(),body);}
}
